from .base_cl_tool import BaseClToolInterface


class CommissioningInterface(BaseClToolInterface):
    OPERATION = 'commissioning'

    def perform_full_commissioning(self, fullfile, validate=False, timeout='15min', keepconn=None, **kwargs):
        """Perform a full commissioning.

        :param string  fullfile: Path to the full commissioning file.
        :param integer keepconn: Time to keep connection. Default is 5min and format is the same as Timeout.
        :param boolean validate: Flag indicating whether to validate SCF file.
        :param string timeout: Timeout for the operation. Default is 15min.

        :return: Path(s) of collected file(s).
        :rtype: list

        :note: To generate a commissioning file, please use the keyword **Upload bts scfc file*** because
               SCFC_*.xml files downloaded via a SSH connection from Fsm are invalid.
        """
        fullfile = fullfile.strip() if fullfile else None
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        config = self.command_store.get(alias).get_config()
        params = self._set_common_parameters(config, kwargs, validate, timeout, keepconn)
        params.update({'fullfile': fullfile})
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['nolog'] if nolog else []
        return self._execute_cl_commissioning_operation(alias=alias, timeout=params.get('timeout'),
                                                        operation=CommissioningInterface.OPERATION, params=params,
                                                        trs_ip=params.get('ne'), flags=flags)

    def perform_full_commissioning_and_wait_for_reset(self, fullfile, validate=False, timeout='15min',
                                                      keepconn=None, **kwargs):
        """Perform a full commissioning and wait for BTS to be reset.

        :param string  fullfile: Path to the full commissioning file.
        :param boolean validate: Flag indicating whether to validate SCF file.
        :param integer keepconn: Time to keep connection. Default is 5min and format is the same as Timeout.
        :param string timeout: Timeout for the operation. Default is 15min.

        :return: Path(s) of collected file(s).
        :rtype: list
        """
        fullfile = fullfile.strip() if fullfile else None
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        config = self.command_store.get(alias).get_config()
        params = self._set_common_parameters(config, kwargs, validate, timeout, keepconn)
        params.update({'fullfile': fullfile})
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['waitforreset']
        if nolog:
            flags.append('nolog')
        return self._execute_cl_commissioning_operation(alias=alias, timeout=params.get('timeout'),
                                                        operation=CommissioningInterface.OPERATION,
                                                        params=params, trs_ip=params.get('ne'), flags=flags)

