    def _set_common_parameters(self, config, kwargs, validate, timeout, keepconn):
        """Set common parameters for commissioning operations."""
        params = {'ne': kwargs.get('ne', config.trs_ip).strip(),
                  'pw': kwargs.get('pw', config.pw).strip(),
                  'timeout': self._convert_to_secs(timeout),
                  'keepconn': self._convert_to_secs(keepconn),
                  }
        params.update({'validate': '{}'.format(config.install_location)}) if validate else None
        return params
